import {SLOTS,GRADES,MATERIALS,RECIPES,itemStats,gearRecipe,enhancementRecipe,canMaterials,spendMaterials,addMaterial} from './economy.mjs?v=0.4';
// A transparent local score, not MIR4's undisclosed Power Score formula.
export const score=v=>Math.round((v.hp||0)+(v.mp||0)*2+(v.atk||0)*10+(v.def||0)*15);
export const itemScore=it=>it?score(itemStats(it)):0;
export function compareItem(s,it){const worn=s.items.find(i=>i.id===s.equipped[it.slot]),a=itemStats(it),b=worn?itemStats(worn):{hp:0,mp:0,atk:0,def:0};return {worn,delta:Object.fromEntries(Object.keys(a).map(k=>[k,a[k]-b[k]])),score:itemScore(it)-itemScore(worn)};}
export function bestEquipment(s){const result=[];for(const slot of Object.keys(SLOTS)){let best=s.items.find(i=>i.id===s.equipped[slot]);for(const it of s.items.filter(i=>i.slot===slot))if(itemScore(it)>itemScore(best))best=it;if(best&&best.id!==s.equipped[slot])result.push(best);}return result;}
export function filterEquipment(s,{slot='all',grade='all',status='all',order='power'}={}){return s.items.filter(it=>(slot==='all'||it.slot===slot)&&(grade==='all'||it.grade===Number(grade))&&(status==='all'||status==='equipped'&&s.equipped[it.slot]===it.id||status==='spare'&&s.equipped[it.slot]!==it.id||status==='trade'&&it.tradable||status==='bound'&&!it.tradable||status==='protected'&&it.protected)).slice().sort((a,b)=>order==='newest'?Number(b.id.slice(5))-Number(a.id.slice(5)):itemScore(b)-itemScore(a)||Number(a.id.slice(5))-Number(b.id.slice(5)));}
export function enhancementPlan(it,target){if(!it||!Number.isInteger(target)||target<=it.enhance||target>8)return null;let gold=0,stone=0;for(let n=it.enhance;n<target;n++){const r=enhancementRecipe({...it,enhance:n});gold+=r.gold;stone+=r.materials.stone;}return {gold,materials:{stone},grade:it.grade,target,steps:target-it.enhance,before:itemStats(it),after:itemStats({...it,enhance:target})};}
export function ascensionRecipe(it){if(!it||it.grade>=4)return null;const r=gearRecipe(it.slot,it.grade+1),materials={...r.materials},replaced={armor:'cloth',weapon:'steel',accessory:'gem',wings:'feather'}[SLOTS[it.slot].group];const saved=materials[replaced];delete materials[replaced];return {...r,materials,replaced,saved};}
export function salvageRecipe(it){return Object.fromEntries(Object.entries(RECIPES[SLOTS[it.slot].group].materials).map(([k,n])=>[k,Math.floor(n*2**(it.tier-1)/2)]).filter(([,n])=>n>0));}
export const sourceMode=k=>({ore:'ore',steel:'ore',herb:'herb',cloth:'herb',energy:'energy',gem:'energy',feather:'energy',essence:'farm'}[k]);
export const equipmentActions={
 equipBest(){const list=bestEquipment(this.s);for(const it of list)this.s.equipped[it.slot]=it.id;this.say(list.length?'Đã mặc '+list.length+' món có lực chiến cao hơn.':'Đã mặc các món tốt nhất theo lực chiến.');return list.length;},
 craftBatch(slot,grade,quantity){const r=gearRecipe(slot,grade);if(!r||!Number.isInteger(quantity)||quantity<1||quantity>20||this.s.items.length+quantity>500)return false;const materials=Object.fromEntries(Object.entries(r.materials).map(([k,n])=>[k,n*quantity]));if(this.s.gold<r.gold*quantity||!canMaterials(this.s,materials,grade))return false;const out=[];for(let n=0;n<quantity;n++)out.push(this.craftGear(slot,grade));return out;},
 enhanceTo(id,target){const it=this.s.items.find(i=>i.id===id),p=enhancementPlan(it,target);if(!p||it.protected||this.s.gold<p.gold||!canMaterials(this.s,p.materials,it.grade))return false;spendMaterials(this.s,p.materials,it.grade);this.s.gold-=p.gold;it.enhance=target;this.say('Đã cường hóa '+SLOTS[it.slot].name+' lên +'+target+'.');return true;},
 salvage(id){const it=this.s.items.find(i=>i.id===id);if(!this.eligibleIngredient(it))return false;const r=salvageRecipe(it);this.s.items=this.s.items.filter(i=>i.id!==id);for(const[k,n]of Object.entries(r))addMaterial(this.s,k,it.grade,n);this.say('Đã phân giải '+SLOTS[it.slot].name+'. Nguyên liệu nhận lại bị khóa.');return r;}
};
